function docListPath(){const inst=selectedInstitutionId();return isPlatform()?"/documents?institution_id="+encodeURIComponent(inst):"/documents"}
function loadDocuments(){if(S.documentsLoading)return Promise.resolve(false);const inst=selectedInstitutionId();if(!inst){S.documents=[];S.documentsError="Prefeitura nao selecionada.";return Promise.resolve(false)}S.documentsLoading=true;S.documentsError="";return request(docListPath()).then(d=>{S.documents=d.documents||[];S.documentsLoaded=true;return true}).catch(e=>{S.documentsError=safeError(e,"Falha ao carregar acervo.");return false}).finally(()=>{S.documentsLoading=false})}
function documentAllowedUnits(){const inst=S.institutions.find(x=>x.id===selectedInstitutionId());return inst?allowedUnitsFor(inst.id):[]}
function documentTypeLabel(v){return label(v).replace("prestacao_contas","Prestacao de contas")}
function isSafeFileReference(v){const ref=t(v);if(/^https?:\/\//i.test(ref))return true;return ref.startsWith("/api/municipal-admin/document-files/")}
function filteredDocuments(){let rows=S.documents.slice();const f=S.documentFilters;if(f.unit_id)rows=rows.filter(d=>safeId(d.unit_id)===safeId(f.unit_id));if(f.document_type)rows=rows.filter(d=>lc(d.document_type)===lc(f.document_type));if(f.status)rows=rows.filter(d=>lc(d.status)===lc(f.status));if(f.search)rows=rows.filter(d=>lc(d.title).includes(lc(f.search)));if(isGestor()){const allowed=documentAllowedUnits().map(u=>safeId(u.id));rows=rows.filter(d=>!safeId(d.unit_id)||allowed.includes(safeId(d.unit_id)))}return rows}
function renderDocumentView(){clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);if(!S.documentsLoaded&&!S.documentsLoading&&!S.documentsError)loadDocuments().then(renderAll);renderDocumentMetrics();renderDocumentList();renderDocumentDetail()}
function renderDocumentMetrics(){const rows=filteredDocuments();S.n.metrics.append(metric("Documentos",rows.length),metric("Ativos",rows.filter(d=>lc(d.status)==="active").length),metric("Arquivados",rows.filter(d=>lc(d.status)==="archived").length),metric("Versoes",rows.reduce((sum,d)=>sum+Number(d.current_version||0),0)))}
function renderDocumentList(){const head=E("div","ma-actions","");head.appendChild(E("h2","","Acervo"));const refresh=E("button","ma-button secondary","Atualizar acervo");refresh.type="button";refresh.onclick=()=>loadDocuments().then(renderAll);head.appendChild(refresh);S.n.list.appendChild(head);if(S.documentsLoading){S.n.list.appendChild(E("p","ma-empty","Carregando acervo..."));return}if(S.documentsError)S.n.list.appendChild(E("p","ma-error",S.documentsError));S.n.list.appendChild(documentFilters());if(canWriteDocuments())S.n.list.appendChild(documentCreateForm());const rows=filteredDocuments();if(!rows.length){S.n.list.appendChild(E("p","ma-empty",S.documentsLoaded?"Nenhum documento encontrado.":"Acervo ainda nao carregado."));return}const list=E("div","ma-list","");rows.forEach(doc=>list.appendChild(documentRow(doc)));S.n.list.appendChild(list)}
function documentFilters(){const form=E("form","ma-form ma-doc-filters","");form.dataset.form="document-filters";const grid=E("div","ma-form-grid","");const units=E("label","","Unidade");const unit=E("select","");unit.name="unit_id";unit.appendChild(E("option","","Todas"));unit.firstChild.value="";documentAllowedUnits().forEach(u=>{const o=E("option","",t(u.name)||u.id);o.value=u.id;if(S.documentFilters.unit_id===u.id)o.selected=true;unit.appendChild(o)});units.appendChild(unit);const typeL=E("label","","Tipo");const type=E("select","");type.name="document_type";type.appendChild(E("option","","Todos"));type.firstChild.value="";DOCUMENT_TYPES.forEach(v=>{const o=E("option","",documentTypeLabel(v));o.value=v;if(S.documentFilters.document_type===v)o.selected=true;type.appendChild(o)});typeL.appendChild(type);const statusL=E("label","","Status");const status=E("select","");status.name="status";[["","Todos"],["active","Ativo"],["archived","Arquivado"]].forEach(([v,txt])=>{const o=E("option","",txt);o.value=v;if(S.documentFilters.status===v)o.selected=true;status.appendChild(o)});statusL.appendChild(status);const searchL=E("label","","Busca por titulo");const search=E("input","");search.name="search";search.value=S.documentFilters.search;search.maxLength=120;searchL.appendChild(search);grid.append(units,typeL,statusL,searchL);form.appendChild(grid);form.oninput=()=>{S.documentFilters=readForm(form);renderAll()};form.onchange=()=>{S.documentFilters=readForm(form);renderAll()};return form}
