function documentRow(doc){const row=E("article","ma-row"+(S.selectedDocumentId===safeId(doc.id)?" is-selected":""),"");row.appendChild(E("strong","",t(doc.title)||"Documento"));row.appendChild(E("span","",[documentTypeLabel(doc.document_type),"Unidade: "+unitName(doc.unit_id),label(doc.status),"Versao atual: "+Number(doc.current_version||0),date(doc.created_at),t(doc.created_by)?"Autor: "+t(doc.created_by):""].filter(Boolean).join(" - ")));const actions=E("div","ma-actions","");const open=E("button","ma-button secondary","Abrir");open.type="button";open.onclick=()=>openDocument(doc.id);actions.appendChild(open);row.appendChild(actions);return row}
function createDocument(form){if(S.saving||!canWriteDocuments())return msg("Acesso somente leitura no acervo.","error");const p=readForm(form);if(!p.title)return msg("Titulo obrigatorio.","error");if(!DOCUMENT_TYPES.includes(p.document_type))return msg("Tipo invalido.","error");const allowed=documentAllowedUnits().map(u=>safeId(u.id));if(p.unit_id&&!allowed.includes(safeId(p.unit_id)))return msg("Unidade nao autorizada para documento.","error");setSaving(form,true);request("/documents",{method:"POST",body:JSON.stringify(p)}).then(d=>{S.selectedDocumentId=safeId(d.document&&d.document.id);msg("Documento criado.","ok");return loadDocuments()}).then(()=>renderAll()).catch(e=>msg(safeError(e,"Erro ao criar documento."),"error")).finally(()=>setSaving(form,false))}
function openDocument(id){const safe=safeId(id);if(!safe)return msg("Documento invalido.","error");S.selectedDocumentId=safe;request("/documents/"+encodeURIComponent(safe)).then(d=>{S.documentDetails[safe]={document:d.document,versions:d.versions||[]};renderAll();msg("Documento aberto.","ok")}).catch(e=>msg(safeError(e,"Erro ao abrir documento."),"error"))}
function renderDocumentDetail(){const id=safeId(S.selectedDocumentId);if(!id){S.n.detail.appendChild(E("p","ma-empty","Abra um documento para ver metadados, versoes e download."));return}const detail=S.documentDetails[id];const baseDoc=S.documents.find(d=>safeId(d.id)===id);if(!detail){if(baseDoc)openDocument(id);S.n.detail.appendChild(E("p","ma-empty","Carregando documento..."));return}const doc=detail.document||baseDoc;if(!doc){S.n.detail.appendChild(E("p","ma-error","Documento nao encontrado."));return}const head=E("div","ma-detail-head","");head.appendChild(E("strong","",t(doc.title)||"Documento"));head.appendChild(E("span","ma-muted",[documentTypeLabel(doc.document_type),"Unidade: "+unitName(doc.unit_id),label(doc.status),"Versao atual: "+Number(doc.current_version||0),date(doc.created_at)].join(" - ")));head.appendChild(E("span","ma-muted",t(doc.description)||"Sem descricao"));const actions=E("div","ma-actions","");const down=E("button","ma-button secondary","Abrir/baixar referencia");down.type="button";down.onclick=()=>downloadDocument(doc.id);actions.appendChild(down);if(canWriteDocuments()&&lc(doc.status)!=="archived"){const arch=E("button","ma-button danger","Arquivar documento");arch.type="button";arch.onclick=()=>archiveDocument(doc.id);actions.appendChild(arch)}head.appendChild(actions);S.n.detail.appendChild(head);S.n.detail.appendChild(versionList(detail.versions||[]));if(canWriteDocuments()&&lc(doc.status)!=="archived")S.n.detail.appendChild(versionForm(doc.id));else if(lc(doc.status)==="archived")S.n.detail.appendChild(E("p","ma-empty","Documento arquivado nao recebe nova versao."))}
